//! K11 hot-plug event journal with generation-safe device identities.
use crate::device::DeviceId;pub const MAX_HOTPLUG_EVENTS:usize=128;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum HotplugKind{Arrived,Authorized,Bound,Online,Suspended,Failed,Removed}
#[derive(Clone,Copy,Debug)]pub struct HotplugEvent{pub sequence:u64,pub device:DeviceId,pub generation:u32,pub kind:HotplugKind}impl HotplugEvent{pub const EMPTY:Self=Self{sequence:0,device:DeviceId(0),generation:0,kind:HotplugKind::Removed};}
pub struct HotplugJournal{events:[HotplugEvent;MAX_HOTPLUG_EVENTS],head:usize,count:usize,next_sequence:u64}impl HotplugJournal{pub const fn new()->Self{Self{events:[HotplugEvent::EMPTY;MAX_HOTPLUG_EVENTS],head:0,count:0,next_sequence:1}}pub fn push(&mut self,device:DeviceId,generation:u32,kind:HotplugKind)->u64{let seq=self.next_sequence;self.next_sequence=self.next_sequence.wrapping_add(1).max(1);self.events[self.head]=HotplugEvent{sequence:seq,device,generation,kind};self.head=(self.head+1)%MAX_HOTPLUG_EVENTS;self.count=self.count.saturating_add(1).min(MAX_HOTPLUG_EVENTS);seq}pub fn since(&self,sequence:u64,mut f:impl FnMut(HotplugEvent)){for e in &self.events{if e.sequence>sequence{f(*e)}}}}
